class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    if @packer
      serialized = @packer.dump(payload)
    else
      serialized = payload
    end
    @store[key] = { payload: serialized, stale: stale }
  end

  def read(key)
    entry = @store[key]
    return nil unless entry

    # If the key was swept, remove it from the store
    if entry[:swept]
      @store.delete(key)
      return nil
    end

    if @packer
      @packer.load(entry[:payload])
    else
      entry[:payload]
    end
  end

  def sweep
    @store.each_key do |key|
      entry = @store[key]
      if entry[:stale]
        @store.delete(key)
      end
    end
  end
end
