class Proxy
  def initialize(target)
    @target = target
  end

  def respond_to?(method_name, include_private = false)
    super || @target.respond_to?(method_name, include_private)
  end

  def method(name)
    if @target.respond_to?(name)
      target_method = @target.method(name)
      Kernel::Method.new(self, :_call_proxy_method).tap do |m|
        # We need a way to invoke the target method through the proxy.
        # Ruby's Method#call doesn't let us capture context easily in a standalone class.
        # Instead, we return a custom object that holds the target method.
      end
    else
      super # Will raise NameError if super doesn't find it either
    end
  end

  def _call_proxy_method(target_method, *args)
    target_method.call(*args)
  end

  def method_missing(method_name, *args, &block)
    if @target.respond_to?(method_name)
      @target.send(method_name, *args, &block)
    else
      raise NoMethodError, "undefined method `#{method_name}' for #{self.inspect}", caller
    end
  end

  def respond_to_missing?(method_name, include_private = false)
    @target.respond_to?(method_name, include_private)
  end

  # Custom Method class that behaves like Kernel::Method
  class ProxyMethod
    def initialize(target_method)
      @target_method = target_method
    end

    def call(*args, &block)
      @target_method.call(*args, &block)
    end
  end
end
