class Proxy
  def initialize(target)
    @target = target
  end

  def respond_to?(method_name, include_private = false)
    return true if @target.respond_to?(method_name, include_private)
    # If Proxy itself defines the method, respond_to? should return true for it
    # But the spec says "returns true for every method name target responds to (in addition to any method Proxy itself directly defines)"
    # This means: respond_to?(:some_method) returns true if:
    # 1. target responds to :some_method, OR
    # 2. Proxy defines :some_method directly
    begin
      method(method_name)
      true
    rescue NameError
      false
    end
  end

  def method(method_name)
    # If target responds to it, delegate
    if @target.respond_to?(method_name)
      original_method = @target.method(method_name)
      # Return a callable ProxyMethod that will call the method on the target
      ProxyMethod.new(self, method_name, original_method)
    else
      # Raise NameError as if the object doesn't have the method
      raise NameError, "undefined method `#{method_name}' for #{self.class} (no method on target either)"
    end
  end

  def method_missing(method_name, *args, &block)
    if @target.respond_to?(method_name)
      @target.send(method_name, *args, &block)
    else
      raise NoMethodError, "undefined method `#{method_name}' for #{self.class}"
    end
  end

  def respond_to_missing?(method_name, include_private = false)
    respond_to?(method_name, include_private)
  end
end

class ProxyMethod
  def initialize(proxy, method_name, original_method)
    @proxy = proxy
    @method_name = method_name
    @original_method = original_method
  end

  def call(*args, &block)
    @proxy.send(@method_name, *args, &block)
  end
end
